import json, sys, re, collections, shlex
files=[l.strip() for l in open('files.txt') if l.strip()]
bash=collections.Counter(); mcp=collections.Counter(); raw=collections.Counter()
SKIP_PREFIX={'sudo','timeout','env','nohup','time'}
def leading(cmd):
    # split on pipes / && / ; / ||
    parts=re.split(r'\|\||&&|\||;|\n',cmd)
    out=[]
    for p in parts:
        p=p.strip()
        if not p: continue
        try: toks=shlex.split(p)
        except Exception: toks=p.split()
        toks=[t for t in toks if t]
        # strip env var prefixes and wrappers
        while toks and (re.match(r'^[A-Za-z_][A-Za-z0-9_]*=',toks[0]) or toks[0] in SKIP_PREFIX):
            toks=toks[1:]
            if toks and toks[0].startswith('-') : toks=toks[1:]
        if not toks: continue
        c=toks[0]
        sub=toks[1] if len(toks)>1 and not toks[1].startswith('-') else ''
        out.append((c,sub))
    return out
for f in files:
    for line in open(f,errors='ignore'):
        try: o=json.loads(line)
        except: continue
        if o.get('type')!='assistant': continue
        m=o.get('message',{})
        for c in m.get('content',[]) if isinstance(m.get('content'),list) else []:
            if c.get('type')!='tool_use': continue
            n=c.get('name','')
            if n=='Bash':
                cmd=c.get('input',{}).get('command','')
                for pair in leading(cmd): bash[pair]+=1
            elif n.startswith('mcp__'): mcp[n]+=1
print("BASH")
for (c,s),n in bash.most_common(80): print(n,c,s)
print("MCP")
for k,n in mcp.most_common(40): print(n,k)
EOF
